CustomField.formula:
IF(AND(ISPICKVAL( Type , 'Product'),ISPICKVAL( PMC_SS_IssueReason__c , 'Product Request')), HYPERLINK($Label.PMC_SS_SAPProductRequest_FioriLink,  'Product Request Fiori Link'), 
	IF( AND(OR(ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Final Approved'),ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Auto Approved')),ISPICKVAL( PMC_SS_ActionReason__c , 'Cancel')), HYPERLINK($Label.PMC_SS_SAPFioriCancelLink,'Cancel Fiori Link'  ),
		IF( AND(OR(ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Final Approved'),ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Auto Approved')),ISPICKVAL( PMC_SS_ActionReason__c , 'Credit')), HYPERLINK($Label.PMC_SS_SAPFioriCreditLink,'Credit Fiori Link' ),
			IF( ISPICKVAL( PMC_SS_ActionReason__c , 'Debit'), HYPERLINK($Label.PMC_SS_SAPFioriDebitLink,'Debit Fiori Link' ),
				IF( AND(OR(ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Final Approved'),ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Auto Approved')),ISPICKVAL( PMC_SS_ActionReason__c , 'Rebill')), HYPERLINK($Label.PMC_SS_SAPFioriRebillLink,'Rebill Fiori Link'),
					IF( AND(OR(ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Final Approved'),ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Auto Approved')),ISPICKVAL( PMC_SS_ActionReason__c , 'Return')), HYPERLINK($Label.PMC_SS_SAPFioriReturnLink,'Return Fiori Link'),
						IF( AND(OR(ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Final Approved'),ISPICKVAL( PMC_SS_ApprovalStatus__c, 'Auto Approved')),ISPICKVAL( PMC_SS_ActionReason__c , 'Reverse Shipment')), HYPERLINK($Label.PMC_SS_SAPFioriReverseShipmentLink,'Reverse Shipment Fiori Link'),
							IF( AND(NOT(ISBLANK(ParentId)), ISPICKVAL( Type , 'Internal'),ISPICKVAL( PMC_SS_IssueReason__c , 'Stock Out / Plant Outage')), HYPERLINK($Label.PMC_SS_SAPFioriStockOutageLink,'Stock Out / Plant Outage Fiori Link'),
									''
									)
							)
						)		
					)
				)
			)
		)
	)
